from math import pow

def calculate_ways(n, k, x, y, z):
    m = 2**k
    MOD = 998244353
    fact = [0] * (k + 2)
    fact[0] = 1
    for i in range(1, k + 2):
        fact[i] = (fact[i-1] * i) % MOD

    ways = [[0] * m for _ in range(m)]
    ways[0][0] = 1

    for i in range(1, 2**k):
        ways[i][i] = 1
        for j in range(k, -1, -1):
            if j >= x:
                ways[i][i] += fact[x] % MOD
                ways[i][i] %= MOD
            if j >= y:
                ways[i][i] -= fact[y] % MOD
                ways[i][i] %= MOD
            if j >= z:
                ways[i][i] += fact[z] % MOD
                ways[i][i] %= MOD

    for l in range(1, 2**k):
        different = set(range(1, l+1))
        for i in different:
            for k in range(1, 2**k):
                if k & i:
                    ways[i][k] = (ways[i][k] + ways[i^k][k] * pow(fact[l-i]^k, -1, MOD)) % MOD

    answer = [ways[i][0] for i in range(m)]
    return answer

