from collections import defaultdict

def can_form_brick(brackets, length, start):
    count = {')': 0, '(': 0}
    for i, char in enumerate(brackets[start:start+length]):
        count[char] += 1
        if count['('] > count[')']:
            return False
    return count['('] == count[')']

def optimal_bricks(bracks):
    num_layers = defaultdict(int)
    height = len(bracks[0][0])
    for brack in bracks:
        if height != len(brack[0]):
            return 0
        for i in range(len(brack)-1):
            num_layers[brack[i][0]] += 1
            num_layers[brack[i+1][-1]] += 1
    for layer in num_layers.values():
        if layer != 0:
            return 0
    height_ = height + 1
    max_length = sum([l[0] for l in bracks])/2
    for layer_len, count in num_layers.items():
        if layer_len % 2 != 0 or layer_len > max_length:
            if count > 0:
                return 0
    for i in range(len(bracks)):
        if len(bracks[i]) <= 1:
            return 1
    max_production = height_-1
    for _ in range(height_):
        for brack in bracks:
            if len(brack) == max_production:
                _max = _ + 1 if _ % 2 else -1
                for i in range(_max, -1, -1):
                    if can_form_brick(''.join(brack), i, _):
                        max_production = min(max_production, i)
            else:               
                break
    return int(max_production < height-1)

