from math import gcd
from typing import List

def splitIntegers(n: int, nums: List[int]) -> bool:
    # If any number is not prime, return False
    if not all(gcd(nums[i], nums[k]) == 1 for i in range(n) for k in range(i+1, n)):
        return False

    # Generate a bitmask where bit i is set if the number i is not prime
    primes = [True] * (n+1)
    primes[0] = primes[1] = False
    for i in range(2, n+1):
        if primes[i]:
            for j in range(i*i, n+1, i):
                primes[j] = False

    # Construct the first group as all prime numbers (1s) and second group as non-prime numbers (2s)
    first_group = [2] * n  # Set all elements to 2 initially
    for k in range(n):
        if not primes[nums[k]]:
            first_group[k] = 1

    return True

