# Function to calculate binomial coefficient modulo p
def mod_binom(n, k, mod):
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    k = min(k, n - k)
    numerator = 1
    for i in range(k):
        numerator = numerator * (n - i) % mod
    denominator = 1
    if 0 < k < n:
        k -= 1
    for i in range(1, min(k + 1, n + 1) + 1):
        denominator = denominator * i % mod
    return numerator * pow(denominator, mod - 2, mod) % mod

# Function to calculate sum of products modulo p
def mod_product_sum(a, b, mod):
    ans = 0
    for i in range(mod):
        ans = (ans + 1L * a * b % mod * pow(2, i, mod)) % mod
    return ans

