def shortest_path_diameter(graph, src):
    graph = [(s, n) for n, s in graph]
    n = len(graph)
    dist = [[0] * n for _ in range(n)]
    dist[src] = [math.inf] * n

    for _ in range(n):
        for u in range(len(graph)):
            min_dist = dist[u][0]
            for v in graph[u]:
                if dist[v][0] < min_dist:
                    min_dist = dist[v][0]
            dist[u][0] = min_dist
            for v in graph[u]:
                dist[v][0] = min(dist[v][0], min_dist + 1)
            max_dist = -math.inf
            for w in graph[u]:
                if w != src:
                    max_dist = max(max_dist, dist[w][0])
            dist[u][0] = max(max_dist, dist[u][0])
    return dist[src][0]

def expected_diameter(graph, queries):
    expected_d = [0] * len(graph)
    for v, u in queries:
        new_graph = [(u, src) for src, _ in graph]
        max_d1 = shortest_path_diameter(new_graph, v)
        if not max_d1:
            expected_d[v] = expected_d[u]
            expected_d[u] = expected_d[v]
        else:
            expected_d[v] += max_d1
            expected_d[u] += max_d1
    return sum(expected_d) / len(graph)

