def win_prob(m: int, n: int) -> tuple[float, float]:
    # Initial probability that Shrek wins
    shrek_win = 1 / 2

    # Tournament probabilities table for efficiency
    tournament_prob = [
        ("shrek_win", 1/2),
        ("donkey_win", 1/2)
    ]

    def add_prob(row: str, column: str, value: float):
        if not tournament_prob:
            tournament_prob.append((row, column, value))
            return

        if column not in ("shrek_win", "donkey_win"):
            raise ValueError("Invalid column segment", column)

        cur_row_value = tournament_prob[-1][0]
        if row != cur_row_value:
            return 

        previous_row_value = tournament_prob[-1][1]
        if column == cur_row_value:
            if previous_row_value == value:
                return
            if previous_row_value < value:
                for new_val in [1 - (row_value + 2 * previous_row_value) / (1 + value + 2 * previous_row_value) for row_value in range(value+2, 2*(n+m)+1)]:
                    tournament_prob.append((row, column, new_val))
                    add_prob(row, column, new_val + previous_row_value)
            if value + 2 * cur_row_value < 2 * (n+m):
                for new_val in [1 - (value + 2 * cur_row_value+1) / (2 * (n+m))] + [1 - (row_value) / (2 * (n+m)) for row_value in range(cur_row_value + 2, value)]:
                    tournament_prob.append((row, column, new_val))
                    add_prob(row, column, new_val + previous_row_value)


    add_prob("donkey_win", "shrek_win", series_prob(m, n))

    return tuple([round(cur_prob[1], 10) for cur_prob in tournament_prob])

def series_prob(m: int, n: int) -> float:
    if m == 0 and n == 0:
        return 1

    for i in range(m+n+2):
        if i == m+n:
            return 1
        elif i == m+n-1:
            return 0
        elif i <= m:
            return 1/2*(1 + series_prob(m-i, n))
        else:
            return 1/2*(1 + series_prob(i, n-1))

if __name__ == "__main__":
    m, n = map(int, input().split())
    print(*win_prob(m, n)) 
    # Use Standard Input format
