import sys
from functools import lru_cache

def solve(n, k, t):
    @lru_cache(maxsize=None)
    def dfs(start, remaining_regions):
        if remaining_regions == 0:
            return 0
        if start >= n or remaining_regions == 1:
            return float('inf')

        best = float('inf')
        all_one = True
        for i in range(start, n + 1, k):
            all_regions = all(t[i + j - k + 1:i + j] == [1] * k for j in range(k))
            best = min(best, float('inf') if not all_regions else max(best, dfs(i, remaining_regions - 1) + t[i] - dfs(start + 1, min(n - i - 1, k - 1))))
        best = max(best, dfs(n, k - 1) + t[start])
        return best

    return max(map(lambda x: dfs(0, x), range(k)), default=0)

n, k = map(int, sys.stdin.readline().split())
t = list(map(int, sys.stdin.readline().split()))

print("%.20f" % solve(n, k, t))
