def compute_distances(points):
    point_dict = {}
    for x, y in points:
        for _x, _y in point_dict:
            d = abs(x - _x) + abs(y - _y)
            if d > 0:
                point_dict[d] = (x, y)
        point_dict[0] = (x, y)
    return point_dict

def find_mayan_points(start, end, total):
    skipped = [0]
    for k in range(1, total // 2 + 1):
        if k <= start < total and start == k + 1 or k <= end < total and end == k + 1:
            skipped.append(k)
        if start + k >= total and start < total - 1:
            skipped.append(start)
        if end - k <= total and end > 1:
            skipped.append(end)
    return sum(1 for k in range(1, total // 2 + 1) if k not in skipped)

