def game_winner(s, l, r):
    import math
    n = len(s)
    r -= l
    diff = 0
    if n == 1:
        return "Alice"
    if r == n:
        return "Bob"
    if l == 1:
        return "Alice"
    diff = math.ceil((r - l) / 2)
    if diff == 0:
        return "Bob"
    if l % diff == 1 and r % diff == 1:
        return "Bob"
    if diff == 2:
        return "Bob"
    if diff % 2 == 0:
        return "Alice"
    return "Bob"
