from math import gcd

def can_split_array(sequence):
    ones, twos = 0, 0
    for num in sequence:
        if gcd(1, num) != 1 and gcd(2, num) == 1:
            return "NO"
        if gcd(num, 1) != 1 and gcd(num, 2) != 1:
            return "NO"
        ones += gcd(num, 1)
        twos += gcd(num, 2)
    if ones > 1 or twos > 1:
        return "NO"
    return "YES"

